import{_ as e,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Lesson 1: What is an AI Programming Assistant?","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-1/lesson-1.md","filePath":"en/modules/module-1/lesson-1.md"}'),i={name:"en/modules/module-1/lesson-1.md"};function s(r,t,l,d,h,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="lesson-1-what-is-an-ai-programming-assistant" tabindex="-1">Lesson 1: What is an AI Programming Assistant? <a class="header-anchor" href="#lesson-1-what-is-an-ai-programming-assistant" aria-label="Permalink to &quot;Lesson 1: What is an AI Programming Assistant?&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand the basic concept of AI programming assistants, know the difference between Codex and traditional chatbots ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Demo first → Explain → Practice</p></blockquote><hr><h2 id="i-demo-first-let-ai-do-something-for-you" tabindex="-1">I. Demo First: Let AI Do Something for You <a class="header-anchor" href="#i-demo-first-let-ai-do-something-for-you" aria-label="Permalink to &quot;I. Demo First: Let AI Do Something for You&quot;">​</a></h2><p>Before we start, I want you to experience what &quot;AI doing work for you&quot; feels like.</p><p>Open ChatGPT (or any AI chat tool) and type this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me write a Python script that reads all .txt files in the current folder, counts the lines in each file, and outputs a summary report.</span></span></code></pre></div><p>See how the AI responds — it will usually give you runnable code directly. Copy this code, save it as <code>count_lines.py</code>, then run it in your terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> count_lines.py</span></span></code></pre></div><p>Congratulations, you&#39;ve just used AI to build a small tool. <strong>You haven&#39;t written a single line of code, but you made AI write it for you.</strong></p><p>This is the power of AI programming assistants.</p><hr><h2 id="ii-from-chatbot-to-agent-that-gets-things-done" tabindex="-1">II. From &quot;Chatbot&quot; to &quot;Agent That Gets Things Done&quot; <a class="header-anchor" href="#ii-from-chatbot-to-agent-that-gets-things-done" aria-label="Permalink to &quot;II. From &quot;Chatbot&quot; to &quot;Agent That Gets Things Done&quot;&quot;">​</a></h2><h3 id="_2-1-chatbot-vs-programming-assistant" tabindex="-1">2.1 Chatbot vs Programming Assistant <a class="header-anchor" href="#_2-1-chatbot-vs-programming-assistant" aria-label="Permalink to &quot;2.1 Chatbot vs Programming Assistant&quot;">​</a></h3><p>You&#39;ve probably used AI tools like ChatGPT, Wenxin Yiyan, or Tongyi Qianwen. They all share one common characteristic: <strong>they can only chat with you</strong>.</p><p>You ask a question, it gives you a text response. You can ask it to write code snippets, but whether the code runs, how to run it, and where to run it — it doesn&#39;t care.</p><p><strong>AI programming assistants (like Codex) are different.</strong> They can not only &quot;chat&quot; but also &quot;do things&quot;:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Chatbot</th><th>AI Programming Assistant (Codex)</th></tr></thead><tbody><tr><td>Answer questions</td><td>✅</td><td>✅</td></tr><tr><td>Write code snippets</td><td>✅</td><td>✅</td></tr><tr><td>Read your project files</td><td>❌</td><td>✅</td></tr><tr><td>Run code and debug</td><td>❌</td><td>✅</td></tr><tr><td>Operate files on your computer</td><td>❌</td><td>✅</td></tr><tr><td>Call external tools</td><td>❌</td><td>✅</td></tr><tr><td>Complete full tasks</td><td>❌</td><td>✅</td></tr></tbody></table><h3 id="_2-2-what-exactly-is-codex" tabindex="-1">2.2 What Exactly is Codex? <a class="header-anchor" href="#_2-2-what-exactly-is-codex" aria-label="Permalink to &quot;2.2 What Exactly is Codex?&quot;">​</a></h3><p><strong>Codex is OpenAI&#39;s AI programming agent.</strong></p><p>Pay attention to two keywords:</p><ul><li><strong>Programming</strong>: Its core capabilities revolve around code — writing code, modifying code, debugging code, explaining code</li><li><strong>Agent</strong>: It&#39;s not a passive tool that answers questions, but an &quot;assistant&quot; that can proactively execute tasks</li></ul><p>You can think of Codex as a <strong>programming-savvy intern</strong>:</p><ul><li>You tell it what you want (in natural language)</li><li>It goes to read relevant files, write code, run tests, find problems, and fix errors</li><li>Finally, it delivers the results to you</li></ul><p><strong>You don&#39;t need to teach it programming knowledge. You just need to tell it what you want.</strong></p><hr><h2 id="iii-real-life-analogies" tabindex="-1">III. Real-Life Analogies <a class="header-anchor" href="#iii-real-life-analogies" aria-label="Permalink to &quot;III. Real-Life Analogies&quot;">​</a></h2><p>If it still feels abstract, let&#39;s use some everyday scenarios to understand:</p><h3 id="analogy-1-codex-a-programming-savvy-intern" tabindex="-1">Analogy 1: Codex = A Programming-Savvy Intern <a class="header-anchor" href="#analogy-1-codex-a-programming-savvy-intern" aria-label="Permalink to &quot;Analogy 1: Codex = A Programming-Savvy Intern&quot;">​</a></h3><p>You&#39;re a new manager at a company and you&#39;ve hired an intern. This intern:</p><ul><li>Can write code</li><li>Can read the files you give them</li><li>Can figure out solutions on their own</li><li>You tell them when they make a mistake, they&#39;ll fix it</li><li>They deliver the results to you for review</li></ul><p><strong>Codex is this intern.</strong> You don&#39;t need to know how to code. You just need to &quot;make requests&quot; like a manager.</p><h3 id="analogy-2-codex-a-multi-talented-secretary" tabindex="-1">Analogy 2: Codex = A Multi-Talented Secretary <a class="header-anchor" href="#analogy-2-codex-a-multi-talented-secretary" aria-label="Permalink to &quot;Analogy 2: Codex = A Multi-Talented Secretary&quot;">​</a></h3><p>Your secretary can help you:</p><ul><li>Organize files (by type, date, etc.)</li><li>Search for information (look up materials online and compile reports)</li><li>Write emails (automatically generate based on your key points)</li><li>Make spreadsheets (you tell them the data format, they format it)</li></ul><p><strong>Codex is this secretary, except it can also write code.</strong></p><h3 id="analogy-3-codex-lego-bricks-instructions" tabindex="-1">Analogy 3: Codex = LEGO Bricks + Instructions <a class="header-anchor" href="#analogy-3-codex-lego-bricks-instructions" aria-label="Permalink to &quot;Analogy 3: Codex = LEGO Bricks + Instructions&quot;">​</a></h3><p>Imagine you want to build a LEGO castle:</p><ul><li><strong>Traditional way</strong>: You piece it together yourself, needing to understand the instructions</li><li><strong>Codex way</strong>: You tell it &quot;I want a castle with towers and walls,&quot; and it builds it for you. You just inspect the result.</li></ul><hr><h2 id="iv-codex-is-not-just-a-code-completion-tool" tabindex="-1">IV. Codex Is Not Just a Code Completion Tool <a class="header-anchor" href="#iv-codex-is-not-just-a-code-completion-tool" aria-label="Permalink to &quot;IV. Codex Is Not Just a Code Completion Tool&quot;">​</a></h2><p>Many people first hear about AI programming tools and think of GitHub Copilot. What is Copilot? It&#39;s a <strong>code completion tool</strong> — you type in your editor, and it helps complete the next line of code.</p><p><strong>Codex is much more powerful than Copilot.</strong></p><table tabindex="0"><thead><tr><th>Comparison</th><th>GitHub Copilot</th><th>Codex</th></tr></thead><tbody><tr><td>Where it works</td><td>Inside editor</td><td>Standalone app / command line</td></tr><tr><td>Capability scope</td><td>Complete code</td><td>Read projects, write code, run commands, call tools</td></tr><tr><td>Task granularity</td><td>Single line / single function</td><td>Complete features / complete projects</td></tr><tr><td>Need programming background?</td><td>Yes (at least read code)</td><td>No (converse in natural language)</td></tr><tr><td>Typical users</td><td>Programmers</td><td>Anyone (including non-programmers)</td></tr></tbody></table><p><strong>Simply put: Copilot is &quot;training wheels&quot; for programmers, Codex is &quot;autopilot&quot; for ordinary people.</strong></p><hr><h2 id="v-summary" tabindex="-1">V. Summary <a class="header-anchor" href="#v-summary" aria-label="Permalink to &quot;V. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>AI Programming Assistant vs Chatbot</td><td>The former can do things, the latter can only chat</td></tr><tr><td>Codex&#39;s Core Positioning</td><td>OpenAI&#39;s AI programming agent, can read files, write code, run commands</td></tr><tr><td>Codex vs Copilot</td><td>Copilot completes code, Codex completes tasks</td></tr><tr><td>Analogy Understanding</td><td>Codex = Programming-Savvy Intern / Multi-Talented Secretary</td></tr></tbody></table><hr><h2 id="vi-post-lesson-thinking" tabindex="-1">VI. Post-Lesson Thinking <a class="header-anchor" href="#vi-post-lesson-thinking" aria-label="Permalink to &quot;VI. Post-Lesson Thinking&quot;">​</a></h2><ol><li>Is there a &quot;repeat, annoying, but must-do&quot; task in your work? Think about it — can Codex help you do it?</li><li>What do you think is the difference between &quot;knowing how to code&quot; and &quot;using AI to program&quot;?</li></ol><blockquote><p>💡 <strong>Hint</strong>: In the next lesson, we&#39;ll show what Codex can specifically do for you. You might discover more tasks you can replace with it.</p></blockquote><hr><h2 id="vii-next-step" tabindex="-1">VII. Next Step <a class="header-anchor" href="#vii-next-step" aria-label="Permalink to &quot;VII. Next Step&quot;">​</a></h2><p><a href="./lesson-2.html">→ Lesson 2: What Can Codex Do for You?</a></p>',55)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
